-- 426: WASSCE English summary multiple-choice set B and grammar short-answer question (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_426_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_426_guard;
INSERT INTO _migration_426_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_006' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Examiners penalise "lifting" whole phrases from the passage in a summary because' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. summaries must always be written in pencil","B. it shows the candidate cannot express the ideas in their own words","C. the passage is the examiner''s property","D. lifted phrases always contain wrong ideas"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Summary questions test comprehension and expression, so copied phrases — even correct ones — do not prove the candidate can restate the ideas.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_006' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_426_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_007' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Choose the best summary of the following. — "Kofi woke before dawn, swept the store, counted the stock and opened the doors before the first customers arrived."' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Kofi woke before dawn and the customers arrived.","B. Kofi swept the store because he woke before dawn.","C. Kofi completed all his opening duties before the customers arrived.","D. Kofi counts the stock whenever customers arrive early."]' AND q.correct_answer IS 'C' AND q.explanation IS 'The best option condenses the three duties into "all his opening duties" and keeps the point that they were finished before customers came; the others lose or distort content.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_007' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_426_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_008' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A passage argues that deforestation causes soil erosion and flooding, and that tree planting is the remedy. Which sentence should NOT appear in its summary?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Deforestation strips the land of its tree cover.","B. The loss of tree cover causes soil erosion and flooding.","C. The tree-planting scheme is intended to reverse the damage.","D. In 1994, one northern village lost its only bridge to a flood."]' AND q.correct_answer IS 'D' AND q.explanation IS 'The bridge incident is a specific illustration, not a main point. The other sentences capture the argument: the problem, its effects and the remedy.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Evaluate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_008' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_426_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_sum_mcq_009' AND NOT (q.topic_id IS 'topic_wassce_english_summary' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A summary requires two points: "The new market has improved trading conditions" and "The new market has created jobs for the youth". Which single sentence combines them best?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The new market has improved trading conditions and created jobs for the youth.","B. The new market has improved trading conditions. It has also created jobs for the youth.","C. Trading conditions have created a new market with jobs for the youth.","D. The new market improved conditions for the trading jobs of the youth."]' AND q.correct_answer IS 'A' AND q.explanation IS 'The correct option joins both points in one sentence without distortion; the first wrong option uses two sentences and the others tangle the relationships.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Summarize' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_sum_mcq_009' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_426_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_gram_sa_001' AND NOT (q.topic_id IS 'topic_wassce_english_grammar' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Correct the concord error in this sentence: "Neither of the two boys have paid his fees."' AND q.question_type IS 'short_answer' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'Neither of the two boys has paid his fees.' AND q.explanation IS 'The subject is "neither", which is singular and takes "has"; "of the two boys" only modifies the subject and does not change its number.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Correct' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_gram_sa_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_eng_s1_sum_mcq_006', 'topic_wassce_english_summary', 'subj_wassce_english', 'exam_wassce', NULL, NULL, 'Examiners penalise "lifting" whole phrases from the passage in a summary because', 'multiple_choice', NULL, '["A. summaries must always be written in pencil","B. it shows the candidate cannot express the ideas in their own words","C. the passage is the examiner''s property","D. lifted phrases always contain wrong ideas"]', 'B', 'Summary questions test comprehension and expression, so copied phrases — even correct ones — do not prove the candidate can restate the ideas.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, NULL);
